    // Check for NULL pointers as per status contract
    if ((temperature == NULL) || (voltage == NULL) || (resistance == NULL) ||
        (next_temperature == NULL) || (current == NULL) || (power == NULL) ||
        (total_power == NULL)) {
        return ADCS_E_NULL;
    }

    // Validate common parameters: finiteness and range
    double tc = thermal_capacity;
    double tr = thermal_resistance;
    double amb = ambient;
    double dt_val = dt;

    if ((!isfinite(tc)) || (!isfinite(tr)) || (!isfinite(amb)) || (!isfinite(dt_val))) {
        return ADCS_E_RANGE;
    }
    if (tc <= 0.0 || tr <= 0.0 || dt_val < 0.0) {
        return ADCS_E_RANGE;
    }

    // Validate axis-specific inputs: finiteness and resistance > 0
    for (int i = 0; i < 3; ++i) {
        double t = (i == 0) ? temperature->x : ((i == 1) ? temperature->y : temperature->z);
        double v = (i == 0) ? voltage->x : ((i == 1) ? voltage->y : voltage->z);
        double r = (i == 0) ? resistance->x : ((i == 1) ? resistance->y : resistance->z);

        if ((!isfinite(t)) || (!isfinite(v)) || (!isfinite(r))) {
            return ADCS_E_RANGE;
        }
        if (r <= 0.0) {
            return ADCS_E_RANGE;
        }
    }

    // Compute per-axis current, power, update temperature, and sum total power
    double total_p = 0.0;

    // Axis X (index 0)
    {
        double r_x = resistance->x;
        double v_x = voltage->x;
        double t_x = temperature->x;

        current->x = v_x / r_x;
        power->x = v_x * current->x; // Equivalent to v_x^2 / r_x
        total_p += power->x;

        double conductive_loss_x = (t_x - amb) / tr;
        double net_heating_x = power->x - conductive_loss_x;
        next_temperature->x = t_x + dt_val * net_heating_x / tc;
    }

    // Axis Y (index 1)
    {
        double r_y = resistance->y;
        double v_y = voltage->y;
        double t_y = temperature->y;

        current->y = v_y / r_y;
        power->y = v_y * current->y;
        total_p += power->y;

        double conductive_loss_y = (t_y - amb) / tr;
        double net_heating_y = power->y - conductive_loss_y;
        next_temperature->y = t_y + dt_val * net_heating_y / tc;
    }

    // Axis Z (index 2)
    {
        double r_z = resistance->z;
        double v_z = voltage->z;
        double t_z = temperature->z;

        current->z = v_z / r_z;
        power->z = v_z * current->z;
        total_p += power->z;

        double conductive_loss_z = (t_z - amb) / tr;
        double net_heating_z = power->z - conductive_loss_z;
        next_temperature->z = t_z + dt_val * net_heating_z / tc;
    }

    *total_power = total_p;

    return ADCS_OK;
}

